700: func (app *App) start(ctx context.Context) error {
701: 	return app.withRollback(ctx, func(ctx context.Context) error {
702: 		if err := app.lifecycle.Start(ctx); err != nil {
703: 			return err
704: 		}
705: 		return nil
706: 	})
707: }
708: 
709: // Stop gracefully stops the application. It executes any registered OnStop
710: // hooks in reverse order, so that each constructor's stop hooks are called
711: // before its dependencies' stop hooks.
712: //
713: // If the application didn't start cleanly, only hooks whose OnStart phase was
714: // called are executed. However, all those hooks are executed, even if some
715: // fail.
716: func (app *App) Stop(ctx context.Context) (err error) {
717: 	defer func() {
718: 		app.log().LogEvent(&fxevent.Stopped{Err: err})
719: 	}()
720: 
721: 	cb := func(ctx context.Context) error {
722: 		defer app.receivers.Stop(ctx)
723: 		return app.lifecycle.Stop(ctx)
724: 	}
725: 
726: 	return withTimeout(ctx, &withTimeoutParams{
727: 		hook:      _onStopHook,
728: 		callback:  cb,
729: 		lifecycle: app.lifecycle,
